window.TL = {"duration": 250.4, "scenes": [{"id": "intro", "label": "Title", "start": 0, "end": 13.534}, {"id": "what", "label": "What is a diagnostic assessment?", "start": 13.534, "end": 28.654}, {"id": "problem", "label": "Problems", "start": 28.654, "end": 50.654}, {"id": "adaptive", "label": "Adaptive diagnostic assessment", "start": 50.654, "end": 68.157}, {"id": "necessary", "label": "Only the necessary questions", "start": 68.157, "end": 76.782}, {"id": "benefit", "label": "Benefits", "start": 76.782, "end": 95.858}, {"id": "how", "label": "How it works", "start": 95.858, "end": 112.464}, {"id": "path", "label": "Algorithm example", "start": 112.464, "end": 149.778}, {"id": "validate", "label": "Validation step", "start": 149.778, "end": 178.769}, {"id": "quick", "label": "Quick Diagnosis", "start": 178.769, "end": 206.127}, {"id": "effects", "label": "Expected effects", "start": 206.127, "end": 241.352}, {"id": "outro", "label": "Thank you", "start": 241.352, "end": 250.4}], "lines": {"l1": {"text": "Hello. Today, I'd like to introduce the development direction and expected benefits of the online Adaptive Diagnostic Assessment for Self-Learning JEI Math.", "start": 3.0, "end": 12.284, "scene": "intro", "chunks": [{"text": "Hello. Today, I'd like to introduce the development direction and expected", "start": 3.0}, {"text": "benefits of the online Adaptive Diagnostic Assessment for Self-Learning JEI Math.", "start": 7.432}]}, "l2": {"text": "First, let me explain the challenges with our current diagnostic assessment.", "start": 14.334, "end": 18.585, "scene": "what", "chunks": [{"text": "First, let me explain the challenges with our current diagnostic assessment.", "start": 14.334}]}, "l3": {"text": "A diagnostic assessment is designed to identify a learner's current level before the learner begins studying and to prescribe a personalized learning program.", "start": 19.235, "end": 27.604, "scene": "what", "chunks": [{"text": "A diagnostic assessment is designed to identify a learner's current level", "start": 19.235}, {"text": "before the learner begins studying and to prescribe a personalized learning program.", "start": 23.126}]}, "l4": {"text": "Currently, accurate diagnosis requires every learner to answer the same set of questions.", "start": 29.454, "end": 34.644, "scene": "problem", "chunks": [{"text": "Currently, accurate diagnosis requires every learner to answer the same", "start": 29.454}, {"text": "set of questions.", "start": 33.641}]}, "l5": {"text": "While using a large number of questions can help improve diagnostic accuracy, it also places a significant burden on learners.", "start": 35.294, "end": 42.207, "scene": "problem", "chunks": [{"text": "While using a large number of questions can help improve diagnostic", "start": 35.294}, {"text": "accuracy, it also places a significant burden on learners.", "start": 38.999}]}, "l6": {"text": "As a result, the process can become less efficient when it comes to identifying each learner's true starting point for learning.", "start": 42.857, "end": 49.604, "scene": "problem", "chunks": [{"text": "As a result, the process can become less efficient when it comes to", "start": 42.857}, {"text": "identifying each learner's true starting point for learning.", "start": 46.416}]}, "l7": {"text": "To address this issue, we are developing an Adaptive Diagnostic Assessment.", "start": 51.454, "end": 55.579, "scene": "adaptive", "chunks": [{"text": "To address this issue, we are developing an Adaptive Diagnostic Assessment.", "start": 51.454}]}, "l8": {"text": "It is a responsive, high-precision diagnostic system in which the next question is adjusted in real time based on whether the learner answers each question correctly or incorrectly within each learning objective.", "start": 56.229, "end": 67.107, "scene": "adaptive", "chunks": [{"text": "It is a responsive, high-precision diagnostic system in which the next", "start": 56.229}, {"text": "question is adjusted in real time based on whether the learner answers", "start": 59.855}, {"text": "each question correctly or incorrectly within each learning objective.", "start": 63.481}]}, "l9": {"text": "The key is not to have learners answer every question, but to present only the questions that are necessary based on their responses.", "start": 68.957, "end": 75.732, "scene": "necessary", "chunks": [{"text": "The key is not to have learners answer every question,", "start": 68.957}, {"text": "but to present only the questions that are necessary based on their responses.", "start": 71.729}]}, "l10": {"text": "This approach improves both diagnostic efficiency and reliability, while also reducing the time required for the assessment.", "start": 77.582, "end": 84.75, "scene": "benefit", "chunks": [{"text": "This approach improves both diagnostic efficiency and reliability,", "start": 77.582}, {"text": "while also reducing the time required for the assessment.", "start": 81.428}]}, "l11": {"text": "In short, it is an assessment system designed to reduce the burden of diagnosis while maintaining its core purpose: accurately identifying the learner's starting point for learning.", "start": 85.4, "end": 94.808, "scene": "benefit", "chunks": [{"text": "In short, it is an assessment system designed to reduce the burden of", "start": 85.4}, {"text": "diagnosis while maintaining its core purpose:", "start": 89.026}, {"text": "accurately identifying the learner's starting point for learning.", "start": 91.391}]}, "l12": {"text": "So, how does the Adaptive Diagnostic Assessment actually work?", "start": 96.658, "end": 100.539, "scene": "how", "chunks": [{"text": "So, how does the Adaptive Diagnostic Assessment actually work?", "start": 96.658}]}, "l13": {"text": "When a question is presented, a correct answer leads to a higher-level question, while an incorrect answer leads to a lower-level question designed to identify any missing concepts.", "start": 101.289, "end": 111.414, "scene": "how", "chunks": [{"text": "When a question is presented, a correct answer leads to a higher-level", "start": 101.289}, {"text": "question, while an incorrect answer leads to a lower-level question", "start": 105.249}, {"text": "designed to identify any missing concepts.", "start": 109.039}]}, "l14": {"text": "For example, instead of having a learner answer every question sequentially from No. 1 to No. 9, we first present a representative core question.", "start": 113.264, "end": 121.597, "scene": "path", "chunks": [{"text": "For example, instead of having a learner answer every question", "start": 113.264}, {"text": "sequentially from No. 1 to No. 9, we first present a representative core question.", "start": 116.852}]}, "l15": {"text": "If the learner answers incorrectly, the system moves down to lower-level concepts, such as No. 3 and then No. 1, to identify where the learning gap begins.", "start": 122.247, "end": 131.637, "scene": "path", "chunks": [{"text": "If the learner answers incorrectly, the system moves down to lower-level", "start": 122.247}, {"text": "concepts, such as No. 3 and then No. 1,", "start": 126.666}, {"text": "to identify where the learning gap begins.", "start": 129.059}]}, "l16": {"text": "On the other hand, if the learner answers correctly, the system moves up to No. 7 and then No. 9 to determine how far the learner's understanding extends.", "start": 132.387, "end": 141.383, "scene": "path", "chunks": [{"text": "On the other hand, if the learner answers correctly,", "start": 132.387}, {"text": "the system moves up to No. 7 and then No.", "start": 135.465}, {"text": "9 to determine how far the learner's understanding extends.", "start": 137.891}]}, "l17": {"text": "In this way, we can minimize the number of questions while accurately pinpointing the learner's actual ability level.", "start": 142.133, "end": 148.728, "scene": "path", "chunks": [{"text": "In this way, we can minimize the number of questions while accurately", "start": 142.133}, {"text": "pinpointing the learner's actual ability level.", "start": 146.056}]}, "l18": {"text": "However, to maintain reliability even with fewer questions, the system also includes a validation step.", "start": 150.578, "end": 156.926, "scene": "validate", "chunks": [{"text": "However, to maintain reliability even with fewer questions,", "start": 150.578}, {"text": "the system also includes a validation step.", "start": 154.25}]}, "l19": {"text": "For each Representative Learning Objective, which represents the core learning goal, we prepare two additional similar questions for thorough evaluation.", "start": 157.576, "end": 165.559, "scene": "validate", "chunks": [{"text": "For each Representative Learning Objective,", "start": 157.576}, {"text": "which represents the core learning goal,", "start": 159.849}, {"text": "we prepare two additional similar questions for thorough evaluation.", "start": 161.964}]}, "l20": {"text": "Answering two out of three correctly results in an \"Understood\" status; otherwise, it is marked as \"Not Understood.\"", "start": 166.309, "end": 172.219, "scene": "validate", "chunks": [{"text": "Answering two out of three correctly results in an \"Understood\" status;", "start": 166.309}, {"text": "otherwise, it is marked as \"Not Understood.\"", "start": 169.958}]}, "l21": {"text": "It is a mechanism to reduce the number of questions while preserving the reliability of the result.", "start": 172.969, "end": 177.719, "scene": "validate", "chunks": [{"text": "It is a mechanism to reduce the number of questions while preserving the", "start": 172.969}, {"text": "reliability of the result.", "start": 176.459}]}, "l22": {"text": "We also prepared a 'Quick Diagnosis' option so it can be used more quickly in the field.", "start": 179.569, "end": 183.805, "scene": "quick", "chunks": [{"text": "We also prepared a 'Quick Diagnosis' option so it can be used more quickly", "start": 179.569}, {"text": "in the field.", "start": 183.172}]}, "l23": {"text": "The Quick Diagnosis first diagnoses Numbers and Operations, a foundational area of mathematics, and then provides a quick report on Numbers and Operations.", "start": 184.455, "end": 193.789, "scene": "quick", "chunks": [{"text": "The Quick Diagnosis first diagnoses Numbers and Operations,", "start": 184.455}, {"text": "a foundational area of mathematics, and then provides a quick report on", "start": 188.055}, {"text": "Numbers and Operations.", "start": 192.386}]}, "l24": {"text": "Using this report, even before the full diagnosis is complete, you can discuss the learner's level of understanding in Numbers and Operations along with the direction for their next steps in learning.", "start": 194.439, "end": 205.077, "scene": "quick", "chunks": [{"text": "Using this report, even before the full diagnosis is complete,", "start": 194.439}, {"text": "you can discuss the learner's level of understanding in Numbers and", "start": 197.77}, {"text": "Operations along with the direction for their next steps in learning.", "start": 201.37}]}, "l25": {"text": "Now, let's look at how the Adaptive Diagnostic Assessment can help in practice.", "start": 206.927, "end": 211.287, "scene": "effects", "chunks": [{"text": "Now, let's look at how the Adaptive Diagnostic Assessment can help in practice.", "start": 206.927}]}, "l26": {"text": "First and foremost, it addresses one of the biggest pain points of the current diagnostic assessment: the excessive number of questions.", "start": 211.937, "end": 218.901, "scene": "effects", "chunks": [{"text": "First and foremost, it addresses one of the biggest pain points of the", "start": 211.937}, {"text": "current diagnostic assessment: the excessive number of questions.", "start": 215.548}]}, "l27": {"text": "With fewer questions, both learners and teachers can experience less burden during the diagnostic process.", "start": 219.551, "end": 225.295, "scene": "effects", "chunks": [{"text": "With fewer questions, both learners and teachers can experience less", "start": 219.551}, {"text": "burden during the diagnostic process.", "start": 223.271}]}, "l28": {"text": "This is expected to improve the efficiency of consultations and classroom management as well.", "start": 225.945, "end": 230.607, "scene": "effects", "chunks": [{"text": "This is expected to improve the efficiency of consultations and classroom", "start": 225.945}, {"text": "management as well.", "start": 229.644}]}, "l29": {"text": "The Adaptive Diagnostic Assessment will first be applied to Self-Learning JEI Math, with the potential to expand the system to other subjects in the future.", "start": 231.257, "end": 240.202, "scene": "effects", "chunks": [{"text": "The Adaptive Diagnostic Assessment will first be applied to Self-Learning", "start": 231.257}, {"text": "JEI Math, with the potential to expand the system to other subjects in the future.", "start": 235.47}]}, "l30": {"text": "This concludes our introduction to the Adaptive Diagnostic Assessment.", "start": 242.152, "end": 245.917, "scene": "outro", "chunks": [{"text": "This concludes our introduction to the Adaptive Diagnostic Assessment.", "start": 242.152}]}, "l31": {"text": "Thank you.", "start": 246.667, "end": 247.455, "scene": "outro", "chunks": [{"text": "Thank you.", "start": 246.667}]}}, "order": ["l1", "l2", "l3", "l4", "l5", "l6", "l7", "l8", "l9", "l10", "l11", "l12", "l13", "l14", "l15", "l16", "l17", "l18", "l19", "l20", "l21", "l22", "l23", "l24", "l25", "l26", "l27", "l28", "l29", "l30", "l31"]};
